<template>
  <div class="app-container" :data-testid="entity+'-detail'">
    <div class="page-header"><div><h1>{{ record ? record.name : 'New '+module.singular }}</h1><p>{{ module.description }}</p></div><div class="page-actions"><el-button icon="el-icon-back" @click="$router.push('/commercialization/'+entity)">Back</el-button><el-button v-if="history.length" icon="el-icon-time" @click="historyVisible=true">Versions</el-button><interaction-notes :title="module.title" :notes="module.notes"/></div></div>
    <div v-if="loadError" class="error-state"><el-alert :title="loadError" type="error" :closable="false"/><el-button @click="load">Retry</el-button></div>
    <div v-else v-loading="loading" class="detail-grid">
      <div>
        <el-alert v-if="error" type="error" :title="error" :closable="false" class="module-notice"><ul v-if="fields.length"><li v-for="field in fields" :key="field">{{ field }}</li></ul><el-button v-if="conflict" type="text" @click="reload">Reload current configuration</el-button></el-alert>
        <el-tabs v-if="record" v-model="tab"><el-tab-pane label="Configuration / Draft" name="draft"/><el-tab-pane :label="'Published v'+record.publishedVersion" name="published" :disabled="!record.published"/></el-tabs>
            <section v-if="tab==='published' && record && record.published" class="section-card"><h2 class="section-title">Published snapshot · Read only</h2><div class="section-body"><commerce-summary :config="record.published" :references="references" :catalog="catalog"/></div></section>
        <el-form v-if="!loading" v-show="tab==='draft'" ref="form" :model="form" :rules="rules" :disabled="busy" label-width="155px" class="suit-form">
          <section class="section-card"><h2 class="section-title">Basic Information</h2><div class="section-body">
            <el-form-item label="Name" prop="name"><el-input v-model.trim="form.name" maxlength="80" show-word-limit data-testid="config-name"/></el-form-item>
            <el-form-item label="Code" prop="code"><el-input v-model.trim="form.code" :disabled="!!record" maxlength="64" placeholder="e.g. content_collection" data-testid="config-code"/><div class="field-help">Unique within this module. Fixed after creation.</div></el-form-item>
            <el-form-item label="Status" prop="status"><el-select v-model="form.status"><el-option label="Active" value="active"/><el-option label="Disabled" value="disabled"/></el-select><div class="field-help">Takes effect after publication. Disabling stops new use and preserves purchased snapshots.</div></el-form-item>
            <el-form-item label="Description"><el-input v-model="form.description" type="textarea" :rows="2" maxlength="1000" show-word-limit/></el-form-item>
          </div></section>
          <template v-if="entity==='products'">
            <section class="section-card"><h2 class="section-title">Fulfillment</h2><div class="section-body">
              <el-form-item label="Product Kind"><el-select v-model="form.kind" :disabled="!!(record && record.publishedVersion)"><el-option label="Membership" value="membership"/><el-option label="Credits · P2" value="credits"/></el-select></el-form-item>
              <template v-if="form.kind==='membership'">
                <el-form-item label="Base Suit"><el-select v-model="form.suitId" filterable placeholder="Choose a published Base suit"><el-option v-for="suit in baseSuits" :key="suit.id" :label="suit.name+' · v'+suit.publishedVersion" :value="suit.id"/></el-select><div class="field-help">Future purchases use the current published suit version. Paid orders keep their purchased version.</div></el-form-item>
                <el-form-item label="Plan Change"><el-select v-model="form.upgradeRule"><el-option label="Immediate upgrade · settlement pending" value="immediate"/><el-option v-if="form.policyVersion!==20261014" label="Legacy: switch at current period end" value="next_cycle"/><el-option label="Blocked while a paid period is active" value="not_allowed"/></el-select><div class="field-help">Current policy: a new plan starts immediately with a new period. Remaining-value settlement needs a confirmed rule; the Demo blocks payment until it is configured.</div></el-form-item>
                <el-form-item label="Included Credits"><p class="form-read-value">{{ suitBenefit }}</p><div class="field-help">Configured on the selected suit. Monthly cadence schedules issues inside the purchased period; other cadences issue once per new period.</div></el-form-item>
              </template>
              <template v-else><el-form-item label="Credit Type"><el-select v-model="form.credits.creditType" placeholder="Choose a credit type"><el-option v-for="type in creditTypes" :key="type.code" :label="type.name" :value="type.code" :disabled="type.legacy&&form.credits.creditType!==type.code"/></el-select></el-form-item><el-form-item label="Credits Amount"><admin-number v-model="form.credits.amount" :min="1" :max="1000000" :precision="0"/></el-form-item><el-form-item label="Purchased Validity"><p v-if="form.credits.validityDays===null">Never expires</p><template v-else><p>Legacy offer: {{ form.credits.validityDays }} days. Existing paid orders keep this snapshot.</p><el-button @click="form.credits.validityDays=null">Make future purchases never expire</el-button></template><div class="field-help">Purchase grants only the selected credit type. It does not activate membership or feature access.</div></el-form-item></template>
            </div></section>
            <section class="section-card"><h2 class="section-title section-title-actions"><span>SKUs</span><el-button icon="el-icon-plus" :disabled="busy" @click="addSku">Add SKU</el-button></h2><div class="section-body">
              <div v-for="(sku,index) in form.skus" :key="index" class="sku-card">
                <div class="sku-card-head"><strong>SKU {{ index+1 }}</strong><el-button type="text" :disabled="publishedSkuIds.includes(sku.id) || form.skus.length===1 || busy" @click="form.skus.splice(index,1)">Remove</el-button></div>
                <div class="two-column-fields">
                  <el-form-item label="SKU ID" label-width="110px"><el-input v-model.trim="sku.id" :disabled="publishedSkuIds.includes(sku.id)"/></el-form-item>
                  <el-form-item label="Channel" label-width="110px"><el-select v-model="sku.channel" :disabled="publishedSkuIds.includes(sku.id)"><el-option label="Web demo" value="web_demo"/><el-option label="Apple" value="apple"/><el-option label="Google" value="google"/></el-select></el-form-item>
                  <el-form-item label="Store Code" label-width="110px"><el-input v-model.trim="sku.storeCode" :disabled="publishedSkuIds.includes(sku.id)"/></el-form-item>
                  <el-form-item label="Status" label-width="110px"><el-select v-model="sku.status"><el-option label="Active" value="active"/><el-option label="Disabled" value="disabled"/></el-select></el-form-item>
                  <el-form-item label="Price" label-width="110px"><admin-number :value="sku.priceCents/100" :min="0.01" :max="1000000" :precision="2" @input="sku.priceCents=Math.round($event*100)"/></el-form-item>
                  <el-form-item label="Currency" label-width="110px"><el-select v-model="sku.currency"><el-option v-for="currency in ['USD','EUR','GBP','CNY']" :key="currency" :label="currency" :value="currency"/></el-select></el-form-item>
                  <el-form-item v-if="form.kind==='membership'" label="Period" label-width="110px"><admin-number v-model="sku.durationDays" :min="1" :max="3650" :precision="0"/><span class="unit-label">days</span></el-form-item>
                  <el-form-item v-if="form.kind==='membership'" label="Billing Cycle" label-width="110px"><el-select :value="sku.billingPeriod||''" @input="$set(sku,'billingPeriod',$event)"><el-option label="Calendar month" value="monthly"/><el-option label="Calendar year" value="annual"/></el-select><div class="field-help">Calendar billing takes precedence over legacy duration days.</div></el-form-item>
                </div>
                <div class="field-help">Published mappings are preserved. Disable an old SKU and add a new mapping.</div>
              </div>
            </div></section>
          </template>
          <section v-if="entity==='content'" class="section-card"><h2 class="section-title">Content Label &amp; Access</h2><div class="section-body">
            <el-form-item label="Content Type"><el-select v-model="form.contentType" :disabled="!!(record && record.publishedVersion)" @change="setContentEntitlement"><el-option v-for="type in ['course','world_tour','training_program','movement','limited_challenge']" :key="type" :label="typeLabel(type)" :value="type"/></el-select></el-form-item>
            <el-form-item label="Access Entitlement"><div class="form-read-value">{{ form.entitlementCode }}</div></el-form-item>
            <el-form-item label="Content Scope"><div class="form-read-value">{{ (definition.scopes.find(scope=>scope.code===form.contentScope)||{}).label || form.contentScope || 'Not assigned' }}</div><router-link :to="{path:'/commercialization/content-management',query:{type:form.contentType,scope:form.contentScope}}" class="field-help">Manage associations in Entitlement Management → Content Management</router-link></el-form-item>
            <el-form-item label="Access Type"><el-radio-group v-model="form.tier"><el-radio-button label="free">Free</el-radio-button><el-radio-button label="premium">Subscription</el-radio-button><el-radio-button label="featured">Independent unlock · P3</el-radio-button></el-radio-group><div class="field-help">{{ contentRule }}</div></el-form-item><el-form-item label="Editorial Pick"><el-switch :value="!!form.recommended" @input="$set(form,'recommended',$event)"/><div class="field-help">Recommendation is independent of paid access.</div></el-form-item>
            <template v-if="form.tier==='featured'"><el-form-item label="Redemption Price"><el-checkbox :value="form.redemptionCredits===null" @change="form.redemptionCredits=$event?null:1">Not configured yet</el-checkbox><admin-number v-if="form.redemptionCredits!==null" v-model="form.redemptionCredits" :min="1" :max="1000000" :precision="0"/><span class="unit-label">Content Credits / successful unlock</span></el-form-item><el-form-item label="Unlock Validity"><p>Permanent for new-policy redemptions. Existing unlocks keep their original contract.</p></el-form-item></template>
            <template v-if="form.contentType==='limited_challenge'&&form.challengeRules"><el-form-item label="Challenge Opens"><el-date-picker :value="form.challengeRules.startsAt" type="datetime" @input="$set(form.challengeRules,'startsAt',$event?new Date($event).toISOString():null)"/></el-form-item><el-form-item label="Challenge Ends"><el-date-picker :value="form.challengeRules.endsAt" type="datetime" @input="$set(form.challengeRules,'endsAt',$event?new Date($event).toISOString():null)"/></el-form-item><el-form-item label="Challenge Target"><el-input v-model="form.challengeRules.target"/><div class="field-help">Challenge business rules stay separate from Join authorization.</div></el-form-item></template>
            <el-form-item v-if="form.contentType!=='limited_challenge'" label="Duration"><admin-number v-model="form.durationMinutes" :min="1" :max="1440" :precision="0"/><span class="unit-label">minutes</span></el-form-item>
            <template v-if="form.contentType==='training_program'"><el-form-item label="Included Workouts"><el-select v-model="form.members" multiple filterable placeholder="Select published workouts"><el-option v-for="item in standaloneContents" :key="item.id" :value="item.id" :label="item.name+' · '+typeLabel(item.published.tier)"/></el-select><div class="field-help">A verified accessible Program grants access to its snapshotted included workouts. No duplicate course redemption is required.</div></el-form-item><el-table :data="includedWorkouts" row-key="id" border><el-table-column prop="name" label="Included Workout" min-width="210"/><el-table-column label="Label" width="110"><template slot-scope="s">{{ typeLabel(s.row.published.tier) }}</template></el-table-column><el-table-column label="Condition" min-width="210"><template slot-scope="s">{{ 'Included via authorized Program' }}</template></el-table-column></el-table></template>
          </div></section>
          <movement-config v-if="entity==='content'&&form.contentType==='movement'&&form.training" v-model="form.training"/>
          <section v-if="entity==='pricing'" class="section-card"><h2 class="section-title">Service Rule</h2><div class="section-body">
            <template v-if="form.policyVersion===20261014"><el-alert v-if="form.sample" class="module-notice" type="info" :closable="false" title="Editable Demo parameters. This configuration does not establish production prices."/><el-form-item label="Service"><el-select v-model="form.servicePurpose" @change="setServicePurpose"><el-option v-for="purpose in servicePurposes" :key="purpose.value" :label="purpose.label" :value="purpose.value"/></el-select></el-form-item>
            <template v-if="featureService"><el-form-item label="Access"><p>{{ featureService }}</p><div class="field-help">The corresponding feature must be in an effective Suit. No Scope, Quota or Credits price.</div></el-form-item><el-form-item label="Credits"><p>No Credits charged.</p></el-form-item></template>
            <template v-else><el-form-item label="Credit Type"><p>AI Coach Credits</p></el-form-item><el-form-item label="Unit"><p>User Turn · one user-initiated request</p><div class="field-help">Internal AI and tool calls never multiply the charge.</div></el-form-item><el-form-item label="Credits / Turn"><el-checkbox :value="form.credits===null" @change="form.credits=$event?null:1">Not configured yet</el-checkbox><admin-number v-if="form.credits!==null" v-model="form.credits" :min="1" :max="1000000" :precision="0"/><div class="field-help">Undefined pricing blocks new requests without charging. A configured request reserves this type of Credits; actual failure releases them.</div></el-form-item></template></template>
            <template v-else><el-alert class="module-notice" type="info" :closable="false" title="Historical service configuration. Its published versions explain the original requests; current MVP service rules are configured separately."/><el-form-item label="Legacy Entitlement"><p>{{ form.entitlementCode }} · {{ form.scope }}</p></el-form-item><el-form-item label="Legacy Price"><admin-number v-model="form.credits" :min="form.code==='plan_activate'?0:1" :max="1000000" :precision="0" :disabled="form.code==='plan_activate'"/><span class="unit-label">Legacy Credits / action</span></el-form-item></template>
          </div></section>
          <section v-if="entity==='campaigns'" class="section-card"><h2 class="section-title">Grant Policy</h2><div class="section-body">
            <el-form-item label="Kind"><el-select v-model="form.kind"><el-option label="Campaign · once per user" value="campaign"/><el-option label="Compensation · once per case/user" value="compensation"/></el-select></el-form-item>
            <el-form-item label="Additional Suit"><el-select v-model="form.suitId" clearable filterable placeholder="Optional" @clear="form.suitId=null"><el-option v-for="suit in additionalSuits" :key="suit.id" :value="suit.id" :label="suit.name+' · v'+suit.publishedVersion"/></el-select><div class="field-help">Base suits cannot be granted by a campaign. {{ form.suitId ? suitBenefit : 'Credits-only grants are supported.' }}</div></el-form-item>
            <el-form-item label="Grant Duration"><admin-number v-model="form.grantDurationDays" :min="1" :max="3650" :precision="0" :disabled="!form.suitId"/><span class="unit-label">days</span></el-form-item>
            <el-form-item label="Extra Credits"><admin-number v-model="form.creditAmount" :min="0" :max="1000000" :precision="0"/><div class="field-help">Extra to the selected suit’s own benefit. 0 means no separate campaign Credits batch.</div></el-form-item>
            <el-form-item label="Credit Type"><el-select v-model="form.creditType" placeholder="Choose a credit type"><el-option v-for="type in creditTypes" :key="type.code" :label="type.name" :value="type.code"/></el-select></el-form-item>
            <el-form-item label="Extra Validity"><admin-number v-model="form.creditValidityDays" :min="1" :max="3650" :precision="0" :disabled="!form.creditAmount"/><span class="unit-label">days after issuance</span></el-form-item>
            <el-form-item label="Recipient Limit"><admin-number v-model="form.maxRecipients" :min="1" :max="10000" :precision="0"/></el-form-item>
            <el-form-item label="Starts"><el-date-picker :value="form.startsAt" type="datetime" placeholder="Immediately" @input="setDate('startsAt',$event)"/></el-form-item>
            <el-form-item label="Ends"><el-date-picker :value="form.endsAt" type="datetime" placeholder="No end date" @input="setDate('endsAt',$event)"/></el-form-item>
          </div></section>
          <div class="save-bar"><div class="save-actions"><el-button type="primary" :loading="action==='save'" :disabled="busy || (record && !dirty)" data-testid="config-save" @click="save">{{ record?'Save Draft':'Create Draft' }}</el-button><el-button v-if="record" :disabled="busy" @click="preview">Preview Changes</el-button><el-button v-if="record" type="success" :disabled="busy || dirty || !hasChanges" data-testid="config-publish" @click="publish">Publish</el-button><el-button v-if="record && record.draft && record.published" :disabled="busy" @click="discard">Discard Draft</el-button></div><span class="muted">{{ dirty?'Unsaved changes':record && record.draft?'Saved draft · not yet effective':'Matches published configuration' }}</span></div>
        </el-form>
      </div>
      <aside class="detail-sidebar"><section class="section-card"><h2 class="section-title">Publication</h2><div class="section-body sidebar-metadata"><div class="metadata-line"><span>Published version</span><strong>{{ record && record.publishedVersion?'v'+record.publishedVersion:'Not published' }}</strong></div><div class="metadata-line"><span>Configuration</span><span>{{ dirty?'Unsaved':record && record.draft?'Saved draft':'Published' }}</span></div><p>{{ entity==='content'?'New starts follow the current published label. Existing redemptions and saved assets remain.':'Only new transactions use new versions. Paid orders, grants, batches and in-flight service prices retain their snapshots.' }}</p><p class="muted">Prices, durations and cadence are sample policies.</p><el-button v-if="entity==='products'" type="text" @click="$router.push('/commercialization/operations')">Preview a purchase</el-button><el-button v-if="entity==='content'" type="text" @click="$router.push('/commercialization/operations')">Preview access / redemption</el-button></div></section><campaign-delivery v-if="entity==='campaigns' && record && record.published" :campaign="record" @changed="load"/></aside>
    </div>
    <el-dialog title="Preview Changes" :visible.sync="previewVisible" width="830px"><template v-if="previewData"><el-alert :title="previewData.policy" type="info" :closable="false"/><div class="preview-impact"><span>Proposed v{{ previewData.nextVersion }}</span><span>{{ previewData.existingOrders }} existing orders</span><span>{{ previewData.existingRedemptions }} existing redemptions</span></div><div v-for="change in previewData.changes" :key="change.field" class="change-block"><strong>{{ labels[change.field] || change.field }}</strong><el-row :gutter="15"><el-col :span="12"><div class="field-label">Published</div><pre>{{ format(change.field,change.before) }}</pre></el-col><el-col :span="12"><div class="field-label">Proposed</div><pre>{{ format(change.field,change.after) }}</pre></el-col></el-row></div><p v-if="!previewData.changes.length" class="muted">No changes.</p></template><span slot="footer"><el-button @click="previewVisible=false">Close</el-button></span></el-dialog>
    <el-dialog title="Published Version History" :visible.sync="historyVisible" width="880px"><el-table :data="history" row-key="version" border><el-table-column label="Version" width="95"><template slot-scope="s">v{{ s.row.version }}</template></el-table-column><el-table-column prop="config.name" label="Name" min-width="200"/><el-table-column label="Published" min-width="180"><template slot-scope="s">{{ dateTime(s.row.publishedAt) }}</template></el-table-column><el-table-column label="Action" width="80"><template slot-scope="s"><el-button type="text" @click="selectedVersion=s.row">View</el-button></template></el-table-column></el-table><div v-if="selectedVersion" class="section-body"><h3>v{{ selectedVersion.version }}</h3><commerce-summary :config="selectedVersion.config" :references="references" :catalog="catalog"/></div><span slot="footer"><el-button @click="historyVisible=false">Close</el-button></span></el-dialog>
  </div>
</template>
<script>
import { getConfig,createConfig,saveConfig,publishConfig,discardConfig,previewConfig,configHistory,listConfigs,money } from '@/api/commerce'
import { getSuits,getSuit,getCatalog } from '@/api/commercialization'
import { getCreditTypes } from '@/api/commerce'
import { creditGrantLabel } from '@/utils/entitlements'
import { modules,defaults,labels,typeLabel } from '../commerce-definitions'
import { dateTime, scopeLabel } from '@/utils/format'
import InteractionNotes from '@/components/InteractionNotes'
import AdminNumber from '@/components/AdminNumber'
import CommerceSummary from '@/components/CommerceSummary'
import CampaignDelivery from '@/components/Commerce/CampaignDelivery'
import MovementConfig from '@/features/movement/MovementConfig'
import {defaultTraining,describeTraining} from '../../../../config/movement-training.cjs'
const clone=value=>JSON.parse(JSON.stringify(value))
export default {
  name:'CommerceConfigurationDetail',components:{InteractionNotes,AdminNumber,CommerceSummary,CampaignDelivery,MovementConfig},props:{entity:{type:String,required:true}},
  data(){return{record:null,form:defaults(this.entity),baseline:'',suits:[],suitDetails:[],catalog:[],contents:[],loading:true,loadError:'',action:'',error:'',fields:[],conflict:false,tab:'draft',bypass:false,history:[],historyVisible:false,selectedVersion:null,previewVisible:false,previewData:null,labels,rules:{name:[{required:true,message:'Enter a name.',trigger:'blur'}],code:[{required:true,message:'Enter a code.',trigger:'blur'},{pattern:/^[a-z][a-z0-9_]{2,63}$/,message:'Use 3–64 lowercase letters, numbers or underscores.',trigger:'blur'}],status:[{required:true,message:'Select a status.',trigger:'change'}]}}},
  computed:{
    module(){return modules[this.entity]},isCreate(){return this.$route.params.id==='create'},busy(){return !!this.action},dirty(){return !!this.baseline && JSON.stringify(this.form)!==this.baseline},hasChanges(){return this.record && this.record.draft && JSON.stringify(this.record.draft)!==JSON.stringify(this.record.published)},
    servicePurposes(){return[{value:'ai_chat',label:'Open-ended AI Coach conversation'},{value:'plan_preview',label:'Discuss / preview a plan with Coach'},{value:'deep_analysis',label:'Workout Result AI Insight'},{value:'weekly_insight',label:'Weekly Report AI Insight'},{value:'plan_activate',label:'Activate a saved Dynamic Plan'}]},
    featureService(){return {deep_analysis:'Workout Result AI Insight',weekly_insight:'Weekly Report AI Insight',plan_activate:'Dynamic Plan'}[this.form.servicePurpose]||null},
    baseSuits(){return this.suits.filter(s=>s.type==='base' && !s.systemDefault && s.publishedVersion)},additionalSuits(){return this.suits.filter(s=>s.type==='additional' && s.publishedVersion)},references(){return Object.fromEntries([...this.suits,...this.contents].map(row=>[row.id,row.name]))},
    creditTypes(){return [...this.catalog.filter(item=>item.type==='consumable_credits').map(item=>({code:item.creditType,name:item.name})),{code:'LEGACY_CREDIT',name:'Legacy Credits',legacy:true}]},
    selectedSuit(){return this.suitDetails.find(s=>s.id===this.form.suitId)},suitBenefit(){const config=this.selectedSuit&&this.selectedSuit.published;if(!config)return 'Choose a suit to review its credit grants.';if(config.creditGrants)return config.creditGrants.map(creditGrantLabel).join('; ')||'No credit grants';const b=config.creditBenefit;return b?`${b.amount} Legacy Credits · ${typeLabel(b.cadence)} · ${b.validityDays} days`:'No credit grants'},
    publishedSkuIds(){return this.record && this.record.published && this.record.published.skus?this.record.published.skus.map(s=>s.id):[]},
    standaloneContents(){return this.contents.filter(row=>row.published && row.published.contentType!=='training_program')},includedWorkouts(){return this.contents.filter(row=>this.form.members && this.form.members.includes(row.id))},
    definition(){return this.catalog.find(row=>row.code===this.form.entitlementCode)||{scopes:[]}},contentRule(){return this.form.tier==='featured'?'Independent redemption is required. Subscription scope access does not replace redemption.':'Access is checked against the assigned Content Scope, rather than inferred from this label.'}
  },
  created(){this.load();window.addEventListener('beforeunload',this.beforeUnload)},beforeDestroy(){window.removeEventListener('beforeunload',this.beforeUnload)},beforeRouteLeave(to,from,next){this.guard(next)},beforeRouteUpdate(to,from,next){this.guard(next)},
  methods:{
    scopeLabel,
    typeLabel,dateTime,money,
    guard(next){if(!this.dirty||this.bypass)return next();this.$confirm('Discard unsaved edits and leave? Saved drafts remain.','Unsaved Changes',{type:'warning',confirmButtonText:'Leave',cancelButtonText:'Stay'}).then(()=>next()).catch(()=>next(false))},
    beforeUnload(event){if(this.dirty){event.preventDefault();event.returnValue=''}},
    setForm(config){this.form=clone(config);if(this.form.contentType==='movement'&&!this.form.training)this.$set(this.form,'training',defaultTraining());if(this.entity==='content'&&this.form.contentScope===undefined)this.$set(this.form,'contentScope',this.form.tier==='free'?(this.form.freeScope||'free_content'):'premium_content');if(this.entity==='products'&&this.form.credits&&this.form.credits.creditType===undefined)this.$set(this.form.credits,'creditType','LEGACY_CREDIT');if(this.entity==='campaigns'&&this.form.creditType===undefined)this.$set(this.form,'creditType','LEGACY_CREDIT');this.baseline=JSON.stringify(this.form);this.$nextTick(()=>{if(this.$refs.form)this.$refs.form.clearValidate()})},
    async load(){this.loading=true;this.loadError='';try{const [suits,catalog,contents]=await Promise.all([getSuits(),getCatalog(),listConfigs('content')]);this.suits=suits;this.catalog=catalog;this.contents=contents;this.suitDetails=await Promise.all(suits.filter(s=>s.publishedVersion).map(s=>getSuit(s.id)));if(this.isCreate)this.setForm(defaults(this.entity));else{const [record,history]=await Promise.all([getConfig(this.entity,this.$route.params.id),configHistory(this.entity,this.$route.params.id)]);this.record=record;this.history=history;this.setForm(record.draft||record.published)}this.error='';this.fields=[];this.conflict=false}catch(e){this.loadError=e.message}finally{this.loading=false}},
    async reload(){if(this.dirty){try{await this.$confirm('Replace your edits with the current server configuration?','Reload',{confirmButtonText:'Reload',cancelButtonText:'Keep edits'})}catch(_){return}}this.load()},
    handleError(e){this.error=e.message;this.fields=e.fields||[];this.conflict=e.reason==='CONFIG_CHANGED'},
    setContentEntitlement(){if(this.form.contentType==='movement'&&!this.form.training)this.$set(this.form,'training',defaultTraining());this.form.entitlementCode={course:'course_access',world_tour:'world_tour_access',training_program:'training_program_access',movement:'movement_access',limited_challenge:'challenge_access'}[this.form.contentType];this.$set(this.form,'contentScope','');if(this.form.contentType!=='course')this.$set(this.form,'freeScope','free_content');if(this.form.contentType==='limited_challenge'){this.$set(this.form,'durationMinutes',null);this.$set(this.form,'challengeRules',{startsAt:null,endsAt:null,target:''});if(this.form.tier==='featured')this.form.tier='premium'}},
    setServicePurpose(){this.form.credits=this.featureService?0:null;},
    setDate(key,value){this.$set(this.form,key,value?new Date(value).toISOString():null)},
    addSku(){this.form.skus.push({id:'sku_'+Date.now(),channel:'web_demo',storeCode:'',priceCents:999,currency:'USD',durationDays:30,status:'active'})},
    valid(){return new Promise(resolve=>this.$refs.form.validate(resolve))},
    async save(){if(this.busy||!(await this.valid()))return;this.action='save';try{if(this.isCreate){const record=await createConfig(this.entity,clone(this.form));this.bypass=true;await this.$store.dispatch('tagsView/deleteView',this.$route);this.$router.replace(`/commercialization/${this.entity}/${record.id}`);this.$message.success('Draft created. Review and publish.')}else{this.record=await saveConfig(this.entity,this.record.id,clone(this.form),this.record.revision);this.setForm(this.record.draft);this.$message.success('Draft saved. Published configuration is unchanged.')}this.error='';this.fields=[]}catch(e){this.handleError(e)}finally{this.action=''}},
    async preview(){if(this.busy||!(await this.valid()))return;this.action='preview';try{this.previewData=await previewConfig(this.entity,this.record.id,clone(this.form));this.previewVisible=true}catch(e){this.handleError(e)}finally{this.action=''}},
    async publish(){if(this.busy||this.dirty||!this.hasChanges)return;try{await this.$confirm(`Publish v${(this.record.publishedVersion||0)+1}? ${this.entity==='content'?'New starts use the new label; independent redemptions remain.':'Existing purchases, grants and Credits keep their snapshots.'}`,'Publish Configuration',{type:'warning',confirmButtonText:'Publish',cancelButtonText:'Cancel'})}catch(_){return}this.action='publish';try{this.record=await publishConfig(this.entity,this.record.id,this.record.revision);this.setForm(this.record.published);this.history=await configHistory(this.entity,this.record.id);this.error='';this.$message.success('New version published.')}catch(e){this.handleError(e)}finally{this.action=''}},
    async discard(){try{await this.$confirm('Discard saved draft and current edits? The published snapshot remains.','Discard Draft',{type:'warning',confirmButtonText:'Discard'})}catch(_){return}this.action='discard';try{this.record=await discardConfig(this.entity,this.record.id,this.record.revision);this.setForm(this.record.published)}catch(e){this.handleError(e)}finally{this.action=''}},
    format(field,value){if(field==='training')return describeTraining(value);if(value===null)return field==='redemptionValidityDays'?'No expiry':'Not set';if(field==='skus')return value.map(s=>`${s.id}: ${money(s.priceCents,s.currency)} · ${s.durationDays||0} days · ${s.status}`).join('\n');if(field==='members')return value.map(id=>this.references[id]||id).join('\n')||'None';if(field==='credits'&&typeof value==='object')return `${value.amount} Credits · ${value.validityDays===null ? "No expiry" : value.validityDays+" days"}`;if(field==='suitId')return this.references[value]||value||'None';if(['startsAt','endsAt'].includes(field))return value?dateTime(value):'No limit';return typeLabel(value)||'—'}
  }
}
</script>
